function extractCompanyPhone(text, cName, addr) {
  // Find cName occurrence
  const regex = new RegExp('(?:^|[^가-힣])' + cName + '(?:[^가-힣]|$)', 'g');
  let match;
  while ((match = regex.exec(text)) !== null) {
    const start = match.index;
    const chunk = text.substring(start, start + 250);
