    const name = res.match(/책임자\s*:\s*([^\r\n]+)/);
    console.log(d, '-> Reg:', reg ? reg[1] : 'NONE', 'Name:', name ? name[1] : 'NONE', 'Phone:', phone ? phone[1] : 'NONE');
  }
}

test();
